source_materials.text:
data "archive_file" "flask_app" {
  type        = "zip"
  output_path = "my_flask_app.zip"
  source_dir  = "source/flask/"
}

data "archive_file" "lambda_function" {
  type        = "zip"
  source_file = "source/lambda_function.py"
  output_path = "source/lambda_function.zip"
}


data "aws_ami" "ubuntu_image" {
  owners      = ["amazon"]
  most_recent = true

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-*-amd64-server-*"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_key_pair" "bob_ec2" {
  key_name   = "cg-ec2-${var.cgid}"
  public_key = file(var.ssh_public_key)
}


resource "aws_instance" "flag_shop_server" {
  ami           = data.aws_ami.ubuntu_image.id
  instance_type = "t3.micro"
  key_name      = aws_key_pair.bob_ec2.key_name

  subnet_id                   = aws_subnet.public_1.id
  associate_public_ip_address = true

  vpc_security_group_ids = [
    aws_security_group.ec2.id
  ]

  root_block_device {
    volume_type           = "gp3"
    volume_size           = 8
    delete_on_termination = true
  }

  provisioner "file" {
    source      = data.archive_file.flask_app.output_path
    destination = "/home/ubuntu/my_flask_app.zip"
    connection {
      type        = "ssh"
      user        = "ubuntu"
      private_key = file(var.ssh_private_key)
      host        = self.public_ip
    }
  }

  provisioner "file" {
    source      = "source/initialize_database.sql"
    destination = "/home/ubuntu/initialize_database.sql"

    connection {
      type        = "ssh"
      user        = "ubuntu"
      private_key = file(var.ssh_private_key)
      host        = self.public_ip
    }
  }

  user_data = <<-EOF
        #!/bin/bash

        echo 'export AWS_ACCESS_KEY_ID=${aws_iam_access_key.web_sqs_manager.id}' >> /etc/environment
        echo 'export AWS_SECRET_ACCESS_KEY=${aws_iam_access_key.web_sqs_manager.secret}' >> /etc/environment
        echo 'export AWS_RDS=${aws_db_instance.rds.address}' >> /etc/environment
        echo 'export AWS_SQS_URL=${aws_sqs_queue.cash_charge.url}' >> /etc/environment
        echo 'export auth=${var.sqs_auth}' >> /etc/environment

        sudo apt update
        sudo apt install -y mysql-client python3-pip unzip
        sudo pip3 install boto3 Flask pymysql
        cd /home/ubuntu
        mysql -h ${aws_db_instance.rds.address} -u ${var.database_username} -p${var.database_password} cash < /home/ubuntu/initialize_database.sql
        unzip my_flask_app.zip
        chmod -R +x my_flask_app/*.py
        cd my_flask_app
        sudo python3 app.py
        EOF

  volume_tags = {
    Name = "cg-${var.cgid}-ec2"
  }
  tags = {
    Name = "cg-linux-ec2-${var.cgid}"
  }
}

resource "aws_iam_user" "web_sqs_manager" {
  name = "cg-web-sqs-manager-${var.cgid}"
}

resource "aws_iam_access_key" "web_sqs_manager" {
  user = aws_iam_user.web_sqs_manager.name
}

resource "aws_iam_policy_attachment" "user_sqs_full_access" {
  name       = "SQSFullAccessAttachment"
  policy_arn = "arn:aws:iam::aws:policy/AmazonSQSFullAccess"
  users      = [aws_iam_user.web_sqs_manager.name]
}


resource "aws_iam_user" "sqs" {
  name = "cg-sqs-user-${var.cgid}"
}

resource "aws_iam_access_key" "sqs" {
  user = aws_iam_user.sqs.name
}

resource "aws_iam_user_policy" "sqs_scenario_assumed_role" {
  name = "cg-sqs-scenario-assumed-role"
  user = aws_iam_user.sqs.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "iam:Get*",
          "iam:List*"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.sqs_send_message.arn
      }
    ]
  })
}



resource "aws_iam_role" "sqs_lambda" {
  name = "cg-sqs-lambda-${var.cgid}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachments_exclusive" "sqs_lambda" {
  role_name = aws_iam_role.sqs_lambda.name
  policy_arns = [
    "arn:aws:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole",
    "arn:aws:iam::aws:policy/service-role/AWSLambdaSQSQueueExecutionRole"
  ]
}


resource "aws_iam_role" "sqs_send_message" {
  name = "cg-sqs-send-message-${var.cgid}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_user.sqs.arn
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "sqs_scenario" {
  name = "cg-sqs"
  role = aws_iam_role.sqs_send_message.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "sqs:GetQueueUrl",
          "sqs:SendMessage"
        ]
        Resource = aws_sqs_queue.cash_charge.arn
      }
    ]
  })
}

locals {
  function_name = "cache-charge"
}


resource "aws_lambda_function" "charging_cash_lambda" {
  function_name = "${local.function_name}-${var.cgid}"
  handler       = "lambda_function.lambda_handler"
  role          = aws_iam_role.sqs_lambda.arn
  runtime       = "python3.12"

  filename         = data.archive_file.lambda_function.output_path
  source_code_hash = filebase64sha256(data.archive_file.lambda_function.output_path)

  timeout = 15

  environment {
    variables = {
      web_url = "http://${aws_instance.flag_shop_server.private_ip}:5000/sqs_process"
      auth    = var.sqs_auth
    }
  }

  vpc_config {
    subnet_ids = [
      aws_subnet.public_1.id
    ]

    security_group_ids = [
      aws_security_group.lambda.id
    ]
  }
}

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name         = "/aws/lambda/${local.function_name}-${var.cgid}"
  skip_destroy = false
}

output "cloudgoat_output_sqsuser_access_key_id" {
  value = aws_iam_access_key.sqs.id
}

output "cloudgoat_output_sqsuser_secret_key" {
  value     = aws_iam_access_key.sqs.secret
  sensitive = true
}

output "web_site_ip" {
  value = "http://${aws_instance.flag_shop_server.public_ip}:5000"
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.6"
    }

    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.74.0"
    }
  }
}

provider "aws" {
  profile = var.profile
  region  = var.region

  default_tags {
    tags = {
      Stack    = var.stack-name
      Scenario = var.scenario-name
    }
  }
}

resource "aws_security_group" "ec2" {
  name        = "cg-ec2-${var.cgid}"
  description = "CloudGoat ${var.cgid} Security Group for EC2 Instance over HTTP"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = concat([aws_vpc.vpc.cidr_block], var.cg_whitelist)
  }
  ingress {
    from_port   = 5000
    to_port     = 5000
    protocol    = "tcp"
    cidr_blocks = concat([aws_vpc.vpc.cidr_block], var.cg_whitelist)
  }
  ingress {
    from_port       = 5000
    to_port         = 5000
    protocol        = "tcp"
    security_groups = [aws_security_group.lambda.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "cg-ec2-${var.cgid}"
  }
}


resource "aws_security_group" "rds" {
  name        = "cg-rds-mysql-${var.cgid}"
  description = "CloudGoat ${var.cgid} Security Group for MySQL RDS Instance"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port = 3306
    to_port   = 3306
    protocol  = "tcp"
    cidr_blocks = [
      "10.10.10.0/24",
      "10.10.20.0/24",
      "10.10.30.0/24",
      "10.10.40.0/24"
    ]
  }
  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = var.cg_whitelist
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "cg-rds-mysql-${var.cgid}"
  }
}


resource "aws_security_group" "lambda" {
  name        = "cg-lambda-${var.cgid}"
  description = "Security group for Lambda function"
  vpc_id      = aws_vpc.vpc.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "cg-lambda-${var.cgid}"
  }
}

resource "aws_sqs_queue" "cash_charge" {
  name                      = "cash_charging_queue"
  delay_seconds             = 0
  max_message_size          = 1024
  message_retention_seconds = 345600
  receive_wait_time_seconds = 0
  sqs_managed_sse_enabled   = true
}

resource "aws_lambda_event_source_mapping" "sqs_event_mapping" {
  event_source_arn = aws_sqs_queue.cash_charge.arn
  function_name    = aws_lambda_function.charging_cash_lambda.arn
  batch_size       = 1
}

variable "profile" {
  description = "The AWS profile to use."
  type        = string
}

variable "region" {
  description = "The AWS region to deploy resources to."
  default     = "us-east-1"
  type        = string
}

variable "cgid" {
  description = "CGID variable for unique naming."
  type        = string
}

variable "cg_whitelist" {
  description = "User's public IP address(es)"
  type        = list(string)
}

variable "stack-name" {
  description = "Name of the stack."
  default     = "CloudGoat"
  type        = string
}

variable "scenario-name" {
  description = "Name of the scenario."
  default     = "sqs_flag_shop"
  type        = string
}

variable "ssh_public_key" {
  description = "SSH Public Key"
  default     = "../cloudgoat.pub"
  type        = string
}

variable "ssh_private_key" {
  description = "SSH Private Key"
  default     = "../cloudgoat"
  type        = string
}

variable "database_name" {
  description = "db_name"
  default     = "cash"
  type        = string
}

variable "database_username" {
  description = "rds_db_username"
  default     = "admin"
  type        = string
}

variable "database_password" {
  description = "rds_db_passwrod"
  default     = "bob12cgv"
  type        = string
}

variable "sqs_auth" {
  description = "sqs_auth"
  default     = "sqs_flag_shop_charging_request_auth"
  type        = string
}

resource "aws_vpc" "vpc" {
  cidr_block           = "10.10.0.0/16"
  enable_dns_hostnames = true

  tags = {
    Name = "cg-${var.cgid}"
  }
}


resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.vpc.id

  tags = {
    Name = "cg-${var.cgid}"
  }
}


# Public Subnets
resource "aws_subnet" "public_1" {
  availability_zone = "${var.region}a"
  cidr_block        = "10.10.10.0/24"
  vpc_id            = aws_vpc.vpc.id

  tags = {
    Name = "cg-${var.cgid}-public-1"
  }
}

resource "aws_subnet" "public_2" {
  availability_zone = "${var.region}b"
  cidr_block        = "10.10.20.0/24"
  vpc_id            = aws_vpc.vpc.id

  tags = {
    Name = "cg-${var.cgid}-public-2"
  }
}

# Private Subnets
resource "aws_subnet" "private_1" {
  availability_zone = "${var.region}a"
  cidr_block        = "10.10.30.0/24"
  vpc_id            = aws_vpc.vpc.id

  tags = {
    Name = "cg-${var.cgid}-private-1"
  }
}

resource "aws_subnet" "private_2" {
  availability_zone = "${var.region}b"
  cidr_block        = "10.10.40.0/24"
  vpc_id            = aws_vpc.vpc.id

  tags = {
    Name = "cg-${var.cgid}-private-2"
  }
}


resource "aws_route_table" "public" {
  vpc_id = aws_vpc.vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = {
    Name = "cg-${var.cgid}-public"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.vpc.id

  tags = {
    Name = "cg-${var.cgid}-private"
  }
}


resource "aws_route_table_association" "public_1" {
  for_each = {
    1 = aws_subnet.public_1.id
    2 = aws_subnet.public_2.id
  }

  subnet_id      = each.value
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  for_each = {
    1 = aws_subnet.private_1.id
    2 = aws_subnet.private_2.id
  }

  subnet_id      = each.value
  route_table_id = aws_route_table.private.id
}
